from test_bufftap import test
setup="""
playerClass='PALADIN'; BuffTap.readinessClassToken=nil; spells={}; book={}
spell(1328548,'Oath of Light'); BuffTap.bookDirty=true
UnitInVehicle=function() return false end
BuffTap.db.helperOath=true; BuffTap.db.oathAssigned={guid=UnitGUID('party1'),name='Ally'}
BuffTap.db.group=false; refresh()
"""
test('Oath targets only the saved party member',setup+"assert(BuffTap.action and BuffTap.action.key=='oath' and BuffTap.action.target=='party1'); assert(BuffTap.button.attrs.spell==1328548)")
test('Oath has no automatic fallback when assignment is empty',setup+'BuffTap.db.oathAssigned={}; refresh(); assert(not BuffTap.action)')
test('Oath does not transfer to another player when assigned GUID leaves',setup+"local old=UnitGUID; UnitGUID=function(u) return u=='party1' and 'Player-Replacement' or old(u) end; refresh(); assert(not BuffTap.action)")
test('Own Oath suppresses a reminder and schedules exact refresh',setup+"aura('party1',1328548,'Oath of Light'); auras.party1[1].sourceUnit='player'; auras.party1[1].duration=300; auras.party1[1].expirationTime=now+200; BuffTap:InvalidateAura('party1'); refresh(); assert(not BuffTap.action and BuffTap.nextWakeDelay<=170.01)")
test('Other paladin Oath is preserved pending coexistence verification',setup+"aura('party1',1328548,'Oath of Light'); auras.party1[1].sourceUnit='target'; BuffTap:InvalidateAura('party1'); refresh(); assert(not BuffTap.action)")
test('Unknown Oath ownership never casts over it',setup+"aura('party1',1328548,'Oath of Light'); BuffTap:InvalidateAura('party1'); refresh(); assert(not BuffTap.action)")
test('Assigned aura updates are watched even without group buffing',setup+"assert(BuffTap:IsWatchedUnit('party1')); aura('party1',1328548,'Oath of Light'); auras.party1[1].sourceUnit='player'; BuffTap.events.scripts.OnEvent(nil,'UNIT_AURA','party1'); advance(.2); assert(not BuffTap.action)")
test('Oath pre-click scans fresh auras',setup+"aura('party1',1328548,'Oath of Light'); auras.party1[1].sourceUnit='player'; BuffTap.button.scripts.PreClick(nil,'LeftButton',true); assert(not BuffTap.action)")
test('Oath pre-click refuses recycled assigned target',setup+"local old=UnitGUID; UnitGUID=function(u) return u=='party1' and 'Player-Replacement' or old(u) end; BuffTap.button.scripts.PreClick(nil,'LeftButton',true); assert(not BuffTap.action)")
test('Oath refuses unreadable target auras',setup+"C_UnitAuras.GetAuraDataByIndex=function() error('restricted') end; BuffTap:InvalidateAura(); refresh(); assert(not BuffTap.action)")
test('Oath refuses unknown spell range',setup+'C_Spell.IsSpellInRange=function() return nil end; C_SpellBook.IsSpellBookItemInRange=function() return nil end; refresh(); assert(not BuffTap.action)')
test('Oath obeys PvP protection',setup+"UnitIsPVP=function(u) return u=='party1' end; refresh(); assert(not BuffTap.action)")
test('Oath does not cast in combat',setup+"combat=true; safety('blocked'); BuffTap.events.scripts.OnEvent(nil,'PLAYER_REGEN_DISABLED'); assert(not BuffTap.button.attrs.type1 and not BuffTap.action)")
test('Oath does not cast with insufficient mana',setup+'C_Spell.IsSpellUsable=function() return false,true end; refresh(); assert(not BuffTap.action and BuffTap.manaBlocked)')
test('Oath can be assigned to self',setup+"BuffTap.db.oathAssigned={guid=UnitGUID('player'),name='Tester'}; refresh(); assert(BuffTap.action and BuffTap.action.target=='player')")
test('Oath does not offer an unlearned talent',setup+'spells[1328548].known=false; BuffTap.bookDirty=true; refresh(); assert(not BuffTap.action)')
test('Oath instant cast is not treated as stationary creation',setup+"GetUnitSpeed=function() return 7 end; refresh(); assert(BuffTap.action and BuffTap.action.key=='oath')")
test('Oath UI shows only Paladin controls',setup+'BuffTap:Options(); local f=BuffTap.helperWindow; assert(f.oathCheck.shown and not f.petCheck.shown and not f.stoneCheck.shown and not f.soulCheck.shown)')
test('Oath assignment uses GUID and keeps full displayed name',setup+"GetUnitName=function() return 'Lexi Preaux' end; assert(BuffTap:SetOathAssignedFromTarget()); assert(BuffTap.db.oathAssigned.guid==UnitGUID('target') and BuffTap.db.oathAssigned.name=='Lexi Preaux')")
test('Oath remains off for other classes even with a copied raw flag', "BuffTap.db.helperOath=true; spell(1328548,'Oath of Light'); assert(not BuffTap:ReadinessEnabled('oath'))")
test('Omen removal leaves saved choices and priorities intact', "BuffTap.db.buffs.omen=true; BuffTap.db.buffs.thorns=false; BuffTap.db.priorities.motw=7; BuffTap.db.priorities.thorns=2; BuffTap:InitDB(); assert(not BuffTap:FindBuff('omen')); assert(BuffTap.db.buffs.thorns==false and BuffTap.db.priorities.motw==7 and BuffTap.db.priorities.thorns==2); for _,b in ipairs(BuffTap:ClassList()) do assert(b.key~='omen') end")
test('Utility defaults off and does not change existing consumable preferences', "BuffTap.db.consumableFamilies.food=true; BuffTap.db.consumableChoices.food=724; BuffTap:InitDB(); assert(not BuffTap:ConsumableFamilySelected(BuffTap:ConsumableFamily('utility'))); assert(BuffTap.db.consumableFamilies.food and BuffTap.db.consumableChoices.food==724)")
test('Utility exact item mapping 246948', "stock(246948,17038); consumables('utility'); BuffTap:SetConsumableChoice(BuffTap:ConsumableFamily('utility'),246948); refresh(); assert(BuffTap.action and BuffTap.action.itemID==246948 and BuffTap.button.attrs.item=='item:246948')")
test('Utility exact item mapping 12820', "stock(12820,17038); consumables('utility'); BuffTap:SetConsumableChoice(BuffTap:ConsumableFamily('utility'),12820); refresh(); assert(BuffTap.action and BuffTap.action.itemID==12820 and BuffTap.button.attrs.item=='item:12820')")
test('Utility exact item mapping 12217', "stock(12217,15852); consumables('utility'); BuffTap:SetConsumableChoice(BuffTap:ConsumableFamily('utility'),12217); refresh(); assert(BuffTap.action and BuffTap.action.itemID==12217 and BuffTap.button.attrs.item=='item:12217')")
test('Utility exact item mapping 9088', "stock(9088,11371); consumables('utility'); BuffTap:SetConsumableChoice(BuffTap:ConsumableFamily('utility'),9088); refresh(); assert(BuffTap.action and BuffTap.action.itemID==9088 and BuffTap.button.attrs.item=='item:9088')")
test('Utility never replaces a recognized active utility effect', "stock(12217,15852); consumables('utility'); aura('player',17038,'Firewater'); BuffTap:InvalidateAura('player'); refresh(); assert(not BuffTap.action)")
test('Utility changed item spell is refused', "stock(12820,99999); consumables('utility'); refresh(); assert(not BuffTap.action)")
test('Utility click rechecks presence of its effect', "stock(12820,17038); consumables('utility'); refresh(); aura('player',17038,'Firewater'); BuffTap.button.scripts.PreClick(nil,'LeftButton',true); assert(not BuffTap.action)")
test('New utility family survives class-inclusive profile copying', "BuffTap.db.consumablesEnabled=true; BuffTap.db.consumableFamilies.utility=true; BuffTap.db.consumableChoices.utility=12217; BuffTap:SaveClassSetup(); local profile=BuffTap.profileDB:GetCurrentProfile(); local character=BuffTap.profileDB.keys.char; BuffTap:CreateSettingsProfile('Utility destination',false); BuffTap.db.consumableFamilies.utility=false; assert(BuffTap:CopySettingsProfile(profile,character)); assert(BuffTap.db.consumableFamilies.utility and BuffTap.db.consumableChoices.utility==12217)")
test('Class-inclusive copy preserves assigned Oath without leaking into shared profile',setup+"BuffTap:SaveClassSetup(); local profile=BuffTap.profileDB:GetCurrentProfile(); local character=BuffTap.profileDB.keys.char; assert(BuffTap.profileDB.profile.helperOath==nil and BuffTap.profileDB.profile.oathAssigned==nil); BuffTap:CreateSettingsProfile('Oath destination',false); BuffTap.db.helperOath=false; assert(BuffTap:CopySettingsProfile(profile,character)); assert(BuffTap.db.helperOath and BuffTap.db.oathAssigned.guid=='Player-party1')")

test('Utility footer fits without overlapping the fourth row', "local old=CreateFrame; CreateFrame=function(...) local f=old(...); f.SetPoint=function(self,...) self.point={...} end; return f end; BuffTap:Options(); local f=BuffTap.options; local row=f.consumableRows[4]; assert(row.point[3]==-356 and -row.point[3]+row.height<440); assert(f.consumeRetry.point[3]==-488 and -f.consumeRetry.point[3]+f.consumeRetry.height<534)")
test('Cross-class copy refuses Oath settings', "local profile=BuffTap.profileDB:GetCurrentProfile(); BuffTap.profileDB.global.characterSetups=BuffTap.profileDB.global.characterSetups or {}; BuffTap.profileDB.global.characterSetups[profile]={Paladin={class='PALADIN',profile=profile,settings={helperOath=true,oathAssigned={guid='Player-Assigned',name='Ally'}}}}; assert(not BuffTap:CopySettingsProfile(profile,'Paladin')); assert(not BuffTap.db.helperOath and not BuffTap.db.oathAssigned.guid)")
test('Oath and utility labels are localized deDE',setup+"BuffTap:Options(); assert(BuffTap.helperWindow.oathCheck.Text.text~='Maintain assigned Oath' and BuffTap.options.consumableRows[4].name.text~='Utility (selected)')",locale='deDE')
test('Oath and utility labels are localized esES',setup+"BuffTap:Options(); assert(BuffTap.helperWindow.oathCheck.Text.text~='Maintain assigned Oath' and BuffTap.options.consumableRows[4].name.text~='Utility (selected)')",locale='esES')
test('Oath and utility labels are localized frFR',setup+"BuffTap:Options(); assert(BuffTap.helperWindow.oathCheck.Text.text~='Maintain assigned Oath' and BuffTap.options.consumableRows[4].name.text~='Utility (selected)')",locale='frFR')
test('Oath and utility labels are localized ptBR',setup+"BuffTap:Options(); assert(BuffTap.helperWindow.oathCheck.Text.text~='Maintain assigned Oath' and BuffTap.options.consumableRows[4].name.text~='Utility (selected)')",locale='ptBR')

